/* Hockey: eerste eigen oefenstof (25-11-2026). Eigen werk van Cluppie; de KNHB-spelregels en de gangbare
   hockeytermen (platte kant, backhand, push, jab, tackle, strafcorner) zijn alleen referentiekader.
   Thema's volgen de leercurve in public/js/sport-hockey.js. Elke vorm krijgt sport: 'hockey' en principes: []
   (de speelwijzen van de club zijn nog voetbal). 'voetbalecht' betekent hier: echt hockey, met doel of doellijn.
   Veiligheid staat in elke vorm: de bal blijft laag (niet boven kniehoogte), geen stick boven de schouder. */
import { P, loop, pass, drib, schot, doel, zone, pion, ring, ploeg, vorm } from './hulp.mjs';

const H = {
  tp: 'Teamsport en plezier', st: 'Stickvaardigheid en balbeheersing', pa: 'Passen en aannemen',
  dr: 'Dribbelen en passeren 1:1', sc: 'Scoren in de cirkel', vl: 'Vrijlopen en aanspeelbaar zijn',
  op: 'Opbouwen van achteruit', v1: 'Verdedigen 1:1 (jab en tackle)', dz: 'Druk zetten en veroveren',
  cv: 'Cirkelverdediging', sa: 'Strafcorner aanvallen', sv: 'Strafcorner verdedigen',
  ob: 'Omschakelen balwinst', ol: 'Omschakelen balverlies',
};
const LAAG = 'Bal laag houden: niet boven kniehoogte spelen, en de stick blijft onder de schouder.';
const BESCHERM = 'Iedereen draagt scheenbeschermers en een bitje; de keeper speelt in volledige uitrusting.';
/* de uitleg is een zin om hardop te zeggen, net als bij de andere vormen (tests/taal.test.mjs) */
const hv = (o) => ({ ...vorm({ ...o, thema: o.thema.map(k => H[k]), uitleg: o.uitleg.startsWith('Zeg: "') ? o.uitleg : `Zeg: "${o.uitleg}"` }), sport: 'hockey', principes: [] });

